import React, { useState, useEffect } from 'react';
import toast, { Toaster } from 'react-hot-toast';
import FileUpload from './components/FileUpload';
import { fetchInventoryData, deleteAllData } from './services/supabase';
import './App.css';

function App() {
  const [inventoryData, setInventoryData] = useState([]);
  const [loading, setLoading] = useState(true);

  const loadInventoryData = async () => {
    setLoading(true);
    const result = await fetchInventoryData();
    setLoading(false);

    if (result.success) {
      setInventoryData(result.data || []);
      if (result.data?.length === 0) {
        toast.info('No inventory data found. Upload an Excel file to get started!');
      }
    } else {
      toast.error('Failed to load inventory data: ' + result.error);
    }
  };

  useEffect(() => {
    loadInventoryData();
  }, []);

  const handleDeleteAll = async () => {
    if (window.confirm('⚠️ Are you sure you want to delete ALL inventory data?')) {
      const result = await deleteAllData();
      if (result.success) {
        toast.success('All inventory data deleted!');
        loadInventoryData();
      } else {
        toast.error('Failed to delete data: ' + result.error);
      }
    }
  };

  return (
    <div className="App">
      <Toaster 
        position="top-right"
        toastOptions={{
          duration: 4000,
          style: {
            background: '#363636',
            color: '#fff',
          },
        }}
      />

      <header className="app-header">
        <h1>📦 Inventory Management System</h1>
        <p>Upload and manage your inventory data</p>
      </header>

      <main className="app-main">
        <FileUpload onUploadSuccess={loadInventoryData} />

        {!loading && inventoryData.length > 0 && (
          <>
            <div className="inventory-summary">
              <div className="summary-card">
                <div className="summary-icon">📊</div>
                <div className="summary-content">
                  <h3>Total Products</h3>
                  <p>{inventoryData.length}</p>
                </div>
              </div>
              <div className="summary-card">
                <div className="summary-icon">📈</div>
                <div className="summary-content">
                  <h3>Low Stock Items</h3>
                  <p>
                    {inventoryData.filter(item => 
                      item.current_inventory_count <= item.safety_stock_level
                    ).length}
                  </p>
                </div>
              </div>
              <div className="summary-card">
                <div className="summary-icon">🚚</div>
                <div className="summary-content">
                  <h3>In Transit</h3>
                  <p>
                    {inventoryData.reduce((sum, item) => 
                      sum + (item.in_transit_quantity || 0), 0
                    )}
                  </p>
                </div>
              </div>
            </div>

            <div style={{textAlign: 'center', marginTop: '20px'}}>
              <button 
                onClick={handleDeleteAll}
                style={{
                  background: '#dc3545',
                  color: 'white',
                  border: 'none',
                  padding: '10px 20px',
                  borderRadius: '8px',
                  cursor: 'pointer',
                  fontSize: '14px'
                }}
              >
                🗑️ Delete All Data
              </button>
            </div>
          </>
        )}

        {!loading && inventoryData.length === 0 && (
          <div className="empty-state">
            <p style={{textAlign: 'center', color: '#666', marginTop: '30px'}}>
              📭 No inventory data yet. Upload an Excel file to get started!
            </p>
          </div>
        )}
      </main>
    </div>
  );
}

export default App;
